{
  "findings": [
    {
      "ref": "[D520]",
      "area": "contact",
      "claim": "A parent reports that direct messages and party chats can be disabled with parental controls, but some chats built into mini-games cannot be turned off.",
      "stance": "risk",
      "quote": "If not, children are automatically exposed to an endless stream of conversation from adults and kids, through text and audio. Roblox limits communication based on age groups, parental settings, and account protections. Chats built into the coding of specific mini-games cannot be disabled, and kids can type text on \"signs\" regardless of communication preferences."
    },
    {
      "ref": "[D520]",
      "area": "money",
      "claim": "A parent reports that Roblox uses Robux, a digital currency, and targeted ads are not shown to users under 13.",
      "stance": "neutral",
      "quote": "Key elements of the games include ads, official product placements, and the need for Robux, the platform's digital currency, to access gated extras. Marketing can be limited, though not completely resolved, by turning off targeted ads. Targeted ads do not appear for users under the age of 13."
    },
    {
      "ref": "[D520]",
      "area": "data",
      "claim": "A parent reports that Roblox may process images used for age verification through third-party providers without guaranteeing a fixed retention period.",
      "stance": "risk",
      "quote": "Images used for age verification may be processed by third-party providers, but Roblox does not publicly guarantee a fixed retention period for the images of children."
    },
    {
      "ref": "[D520]",
      "area": "age_gating",
      "claim": "A parent reports that the age verification system can make mistakes, potentially loosening protections for younger users or restricting older users.",
      "stance": "risk",
      "quote": "Roblox uses this information to estimate or verify a user’s age and place accounts into age-based categories. Under Roblox’s newer system, users age 5 to 8 may be placed into \"Roblox Kids\" accounts, while users age 9 to 15 may be placed into \"Roblox Select\" accounts. However, the system can make mistakes. Incorrect age estimates may loosen built-in protections, such as chat restrictions or access limits, while some adults may be incorrectly categorized as younger users and face additional restrictions."
    },
    {
      "ref": "[D520]",
      "area": "content",
      "claim": "A parent reports that extreme violence, inappropriate language, and sexually explicit content can be accessed by users as young as 5 due to inaccurate content labels.",
      "stance": "risk",
      "quote": "Content labels on games are often inaccurate, leading to many violent or otherwise explicit experiences being immediately accessible to users as young as 5. After creating an account, kids gain access to millions of games where they can be encouraged to engage in behavior like fighting, killing, and other inappropriate actions."
    },
    {
      "ref": "[D520]",
      "area": "developer_record",
      "claim": "A parent reports that Roblox has faced fines, breaches, lawsuits, or regulatory actions.",
      "stance": "neutral",
      "quote": "Roblox uses AI-based age estimation and verification systems for some users. Users over age 13 may be asked to submit a live selfie or upload a government ID to access certain communication features. Roblox uses this information to estimate or verify a user’s age and place accounts into age-based categories."
    }
  ]
}
